import { test, expect } from '@playwright/test';

test.describe('Item Details View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/items');
  });

  test('should navigate to item details when an item is clicked', async ({ page }) => {
    const itemName = 'Sample Item';
    await page.getByText(itemName).click();
    await expect(page.getByRole('heading', { name: itemName })).toBeVisible();
  });

  test('should display correct item details', async ({ page }) => {
    const itemName = 'Sample Item';
    await page.getByText(itemName).click();
    await expect(page.getByLabel('Description')).toHaveText('This is a sample item description.');
    await expect(page.getByLabel('Price')).toHaveText('$19.99');
  });
});
